// ---- lib/followups.js (generated from source - do not edit here) ----
// ---------------------------------------------------------------------------
// Follow-up scheduling.
// One rule dominates: a reply at any stage stops the sequence. That is enforced
// in three places - here, in the follow-up workflow's guard, and in a database
// trigger - because getting it wrong means messaging someone who already
// answered.
// ---------------------------------------------------------------------------

const STOP_STATUSES = ['REPLIED', 'INTERESTED', 'NOT_INTERESTED', 'NURTURE', 'CLOSED', 'OPTED_OUT'];
const FOLLOWUP_KINDS = ['followup_1', 'followup_2', 'followup_3_final'];

/** Should the sequence keep running for this lead? */
function shouldStopSequence(lead = {}) {
  if (lead.replied_at) return { stop: true, reason: 'reply_received' };
  if (STOP_STATUSES.includes(lead.status)) return { stop: true, reason: `status_${String(lead.status).toLowerCase()}` };
  if (['REPLIED', 'CONVERSATION', 'INTERESTED', 'NURTURE', 'NOT_INTERESTED', 'CLOSED'].includes(lead.stage)) {
    return { stop: true, reason: `stage_${String(lead.stage).toLowerCase()}` };
  }
  if (lead.suppressed) return { stop: true, reason: 'suppressed' };
  return { stop: false, reason: null };
}

/** Day offsets for a campaign, falling back to the global default. */
function offsetsFor(campaign, defaults) {
  const fromCampaign = campaign?.followups?.day_offsets;
  if (Array.isArray(fromCampaign) && fromCampaign.length) return fromCampaign;
  return (defaults?.steps ?? []).filter((s) => s.step > 0).map((s) => s.day_offset);
}

/**
 * Build the schedule for a lead whose initial DM was just sent.
 * @returns [{ step, kind, due_at }]
 */
function buildSchedule(sentAt, campaign, defaults) {
  if (campaign?.followups?.enabled === false) return [];
  const offsets = offsetsFor(campaign, defaults);
  const window = campaign?.followups?.send_window ?? defaults?.send_window;
  const base = sentAt instanceof Date ? sentAt : new Date(sentAt);
  return offsets.slice(0, FOLLOWUP_KINDS.length).map((days, i) => {
    const due = new Date(base.getTime() + days * 86400000);
    return {
      step: i + 1,
      kind: FOLLOWUP_KINDS[i],
      day_offset: days,
      due_at: nextSendSlot(due, window).toISOString()
    };
  });
}

/**
 * Move a timestamp to the next allowed sending slot.
 * Interpreted in the campaign's timezone by the caller - here we work on the
 * date object's local-equivalent parts supplied in `window`.
 */
function nextSendSlot(date, window) {
  if (!window) return date;
  const out = new Date(date.getTime());
  const days = window.days ?? [1, 2, 3, 4, 5];
  const start = window.start_hour ?? 9;
  const end = window.end_hour ?? 18;

  for (let guard = 0; guard < 14; guard += 1) {
    const dow = out.getUTCDay();
    const hour = out.getUTCHours();
    if (!days.includes(dow)) {
      out.setUTCDate(out.getUTCDate() + 1);
      out.setUTCHours(start, 0, 0, 0);
      continue;
    }
    if (hour < start) { out.setUTCHours(start, 0, 0, 0); return out; }
    if (hour >= end) {
      out.setUTCDate(out.getUTCDate() + 1);
      out.setUTCHours(start, 0, 0, 0);
      continue;
    }
    return out;
  }
  return out;
}

/** The step config (intent, char limit) for a given follow-up kind. */
function stepConfig(kind, defaults) {
  return (defaults?.steps ?? []).find((s) => s.kind === kind) ?? null;
}

/**
 * Daily release gate. The queue never hands out more than the campaign allows,
 * so a backlog cannot turn into a burst.
 */
function applyDailyLimits(items, { sentToday = 0, limit = 30 } = {}) {
  const remaining = Math.max(0, limit - sentToday);
  return { release: items.slice(0, remaining), held: items.slice(remaining), remaining };
}

/** What happens once the final follow-up went out without a reply. */
function afterFinal(defaults) {
  return defaults?.after_final ?? { status: 'NO_RESPONSE', move_to_stage: 'NURTURE', nurture_recheck_days: 90 };
}

// ---- node logic ----
const FOLLOWUP_DEFAULTS = {"version":1,"note":"Follow-up cadence. Every interval is configurable per campaign (campaign.followups overrides this file). A reply at ANY step cancels every pending follow-up for that lead - enforced in lib/followups.js and by a DB trigger in db/migrations/0003_functions.sql.","timezone":"America/Los_Angeles","send_window":{"start_hour":9,"end_hour":18,"days":[1,2,3,4,5]},"stop_on_reply":true,"stop_on_statuses":["REPLIED","INTERESTED","NOT_INTERESTED","NURTURE","CLOSED","OPTED_OUT"],"max_followups":3,"steps":[{"step":0,"day_offset":0,"kind":"initial","label":"Initial DM","prompt":"05-outreach-message","intent":"Open a conversation with one specific observation and one relevant question."},{"step":1,"day_offset":2,"kind":"followup_1","label":"Follow-up #1 - short continuation","prompt":"06-followup-message","intent":"One or two lines that continue the original thought. Never 'just following up'. Re-state the specific observation in different words and make replying take five seconds.","max_chars":300},{"step":2,"day_offset":5,"kind":"followup_2","label":"Follow-up #2 - business observation / value","prompt":"06-followup-message","intent":"Add something they did not have before: a concrete observation about how similar brands in their niche handle this, or a number from comparable work. No pitch deck, no service list.","max_chars":450},{"step":3,"day_offset":9,"kind":"followup_3_final","label":"Final follow-up - close the loop","prompt":"06-followup-message","intent":"Respectful close-the-loop. Acknowledge the timing may be wrong, leave the door open, ask nothing more than a yes/no. This is the last automated touch.","max_chars":300,"final":true}],"after_final":{"status":"NO_RESPONSE","move_to_stage":"NURTURE","nurture_recheck_days":90},"rate_limits":{"note":"Human-operated sending pace. The queue will not release more than this many messages per day per sending account.","max_new_dms_per_day":30,"max_followups_per_day":40,"min_seconds_between_sends":45}};

const campaigns = ($('Load Active Campaigns').first().json || []);
const sent = ($('Count Sent Today').first().json || []);
const queued = ($input.first().json || []);

const byCampaign = new Map();
for (const c of Array.isArray(campaigns) ? campaigns : [campaigns]) byCampaign.set(c.id, c);

const sentCounts = {};
for (const row of Array.isArray(sent) ? sent : []) {
  sentCounts[row.campaign_id] ??= { initial: 0, followup: 0 };
  if (row.kind === 'initial') sentCounts[row.campaign_id].initial += 1;
  else sentCounts[row.campaign_id].followup += 1;
}

const released = [];
const held = [];

for (const campaignId of new Set((Array.isArray(queued) ? queued : []).map((q) => q.campaign_id))) {
  const campaign = byCampaign.get(campaignId) || {};
  const limits = campaign.followups?.rate_limits ?? FOLLOWUP_DEFAULTS.rate_limits;
  const items = queued.filter((q) => q.campaign_id === campaignId);

  const initials = items.filter((i) => i.kind === 'initial');
  const followups = items.filter((i) => i.kind !== 'initial');

  const initialGate = applyDailyLimits(initials, {
    sentToday: sentCounts[campaignId]?.initial ?? 0,
    limit: campaign.outreach?.daily_outreach_target ?? limits.max_new_dms_per_day
  });
  const followupGate = applyDailyLimits(followups, {
    sentToday: sentCounts[campaignId]?.followup ?? 0,
    limit: limits.max_followups_per_day
  });

  const mode = campaign.outreach?.sending_mode ?? 'manual';
  for (const item of [...initialGate.release, ...followupGate.release]) {
    released.push({ ...item, send_mode: mode, min_seconds_between_sends: limits.min_seconds_between_sends ?? 45 });
  }
  held.push(...initialGate.held, ...followupGate.held);
}

if (!released.length) {
  return [{ json: { released: 0, held: held.length, note: 'Daily cap reached or nothing approved.', items: [] } }];
}
return released.map((item) => ({ json: { ...item, released_total: released.length, held_total: held.length } }));

// Everything the operator needs in one place: who, the profile link, the exact
// approved text, and the pacing to respect. The send itself is theirs; the
// console calls wf07 /mark-sent afterwards.
return $input.all().map((item) => {
  const row = item.json;
  return { json: {
    outreach_id: row.outreach_id,
    lead_id: row.lead_id,
    lead_ref: row.public_ref,
    business_name: row.business_name,
    instagram_handle: row.instagram_handle,
    profile_url: row.instagram_url || (row.instagram_handle ? 'https://www.instagram.com/' + row.instagram_handle + '/' : null),
    direct_url: row.instagram_handle ? 'https://www.instagram.com/direct/new/?username=' + row.instagram_handle : null,
    target_contact: row.target_contact,
    kind: row.kind,
    message: row.message_to_send,
    approved_by: row.approved_by,
    approved_at: row.approved_at,
    icp_score: row.icp_score,
    priority: row.priority,
    pacing_seconds: row.min_seconds_between_sends,
    instructions: 'Open the profile, paste the message, send it, then press "Mark as sent".'
  } };
});
